algorithms.pseudocode:
for r in instr.dest_logical_regs:
    if r < num_logical_regs:
        sr_reg_digest_table[r].valid = 0
        sr_reg_digest_table[r].payload = instr.rob_index
        sr_reg_digest_table[r].decay_ctr = decay_threshold

for r in range(num_logical_regs):
    if sr_reg_digest_table[r].decay_ctr > 0:
        sr_reg_digest_table[r].decay_ctr -= 1
        if sr_reg_digest_table[r].decay_ctr == 0:
            sr_reg_digest_table[r].valid = 0

for r in instr.dest_logical_regs:
    if r < num_logical_regs:
        if (not sr_reg_digest_table[r].valid) and (sr_reg_digest_table[r].payload == instr.rob_index):
            val = instr.value
            fmt = instr.format
            if fmt == 'INT':
                lz = min(count_leading_bits_matching_msb(val), 63)
                tz = min(count_trailing_bits_matching_lsb(val), 63)
                lsb = val & 0x3F
                digest = (tz & 0x3F) ^ ((lz & 0x3F) << 3) ^ (lsb << 6)
            elif fmt == 'FP32':
                digest = ((val >> 26) & 0x3F) << 3
            elif fmt == 'FP64':
                digest = ((val >> 55) & 0x1FF) << 3
            elif fmt == 'FP16':
                digest = ((val >> 13) & 0x7) << 3
            elif fmt == 'FLAG':
                fv = val & 0xF
                digest = fv | (fv << 4) | (fv << 8)
            else:
                digest = 0
            sr_reg_digest_table[r].payload = digest & 0xFFF
            sr_reg_digest_table[r].valid = 1
            sr_reg_digest_table[r].decay_ctr = decay_threshold

for r in range(num_logical_regs):
    if (not sr_reg_digest_table[r].valid) and (sr_reg_digest_table[r].payload >= squashed_rob_index):
        sr_reg_digest_table[r].payload = 0
